code = '''import re
import json

def parse_skill_md(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    name_match = re.search(r'^#\\s+(.+)$', content, re.MULTILINE)
    project_name = name_match.group(1).strip() if name_match else 'Unknown'

    version_match = re.search(r'\\*\\*Version:\\*\\*\\s*([\\d.]+)', content)
    version = version_match.group(1) if version_match else 'Unknown'

    license_match = re.search(r'\\*\\*License:\\*\\*\\s*(\\w+)', content)
    license_val = license_match.group(1) if license_match else 'Unknown'

    models = []
    in_models = False
    for line in content.split(chr(10)):
        if '## Supported Models' in line:
            in_models = True
            continue
        if in_models:
            if line.startswith('-'):
                models.append(line.strip()[1:].strip())
            elif line.strip() and not line.startswith(' '):
                break

    return {
        'project_name': project_name,
        'version': version,
        'license': license_val,
        'supported_models': models
    }

def main():
    summary = parse_skill_md('SKILL.md')
    with open('output.json', 'w', encoding='utf-8') as f:
        json.dump(summary, f, indent=2)
    print('Summary written to output.json')
    print(json.dumps(summary, indent=2))

if __name__ == '__main__':
    main()
'''
with open('token_guard_summary.py', 'w') as f:
    f.write(code)
print('Done')
